import math
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st

from solution import triangle_area


def reference_area(a, b, c):
    if a + b <= c or a + c <= b or b + c <= a:
        return -1
    p = (a + b + c) / 2
    return round(math.sqrt(p * (p - a) * (p - b) * (p - c)), 2)


def test_spec_example_right_triangle():
    assert triangle_area(3, 4, 5) == 6.00


def test_spec_example_invalid_triangle():
    assert triangle_area(1, 2, 10) == -1


def test_degenerate_equality_first_side_largest():
    assert triangle_area(2, 1, 1) == -1


def test_degenerate_equality_all_permutations():
    assert triangle_area(1, 2, 1) == -1
    assert triangle_area(1, 1, 2) == -1
    assert triangle_area(5, 3, 2) == -1
    assert triangle_area(3, 5, 2) == -1
    assert triangle_area(2, 3, 5) == -1


def test_known_equilateral_triangle():
    # side 2: p=3, area=sqrt(3*1*1*1)=sqrt(3)=1.732... -> 1.73
    assert triangle_area(2, 2, 2) == 1.73


def test_known_right_triangle_5_12_13():
    assert triangle_area(5, 12, 13) == 30.00


def test_valid_triangle_positive_area():
    assert triangle_area(4, 5, 6) == reference_area(4, 5, 6)
    assert triangle_area(4, 5, 6) > 0


@given(
    a=st.floats(min_value=0.5, max_value=10, allow_nan=False, allow_infinity=False),
    b=st.floats(min_value=0.5, max_value=10, allow_nan=False, allow_infinity=False),
    c=st.floats(min_value=0.5, max_value=10, allow_nan=False, allow_infinity=False),
)
def test_matches_heron_reference_model(a, b, c):
    assert triangle_area(a, b, c) == reference_area(a, b, c)


@given(
    b=st.floats(min_value=0.5, max_value=10, allow_nan=False, allow_infinity=False),
    c=st.floats(min_value=0.5, max_value=10, allow_nan=False, allow_infinity=False),
)
def test_degenerate_sum_equals_third_is_invalid(b, c):
    # boundary: sum of two sides exactly equals third -> not > so invalid
    assert triangle_area(b + c, b, c) == -1
    assert triangle_area(b, b + c, c) == -1
    assert triangle_area(b, c, b + c) == -1


@given(
    b=st.floats(min_value=0.5, max_value=10, allow_nan=False, allow_infinity=False),
    c=st.floats(min_value=0.5, max_value=10, allow_nan=False, allow_infinity=False),
    excess=st.floats(min_value=0.01, max_value=10, allow_nan=False, allow_infinity=False),
)
def test_strictly_invalid_triangle_returns_minus_one(b, c, excess):
    a = b + c + excess
    assert triangle_area(a, b, c) == -1
    assert triangle_area(b, a, c) == -1
    assert triangle_area(b, c, a) == -1


@given(
    a=st.floats(min_value=0.5, max_value=10, allow_nan=False, allow_infinity=False),
    b=st.floats(min_value=0.5, max_value=10, allow_nan=False, allow_infinity=False),
    c=st.floats(min_value=0.5, max_value=10, allow_nan=False, allow_infinity=False),
)
def test_valid_triangle_positive_and_rounded(a, b, c):
    assume(a + b > c and a + c > b and b + c > a)
    result = triangle_area(a, b, c)
    assert result != -1
    assert result > 0
    assert result == round(result, 2)


@given(
    a=st.floats(min_value=0.5, max_value=10, allow_nan=False, allow_infinity=False),
    b=st.floats(min_value=0.5, max_value=10, allow_nan=False, allow_infinity=False),
    c=st.floats(min_value=0.5, max_value=10, allow_nan=False, allow_infinity=False),
)
def test_permutation_invariance(a, b, c):
    assert triangle_area(a, b, c) == triangle_area(b, a, c)
    assert triangle_area(a, b, c) == triangle_area(c, b, a)
    assert triangle_area(a, b, c) == triangle_area(a, c, b)


@given(
    a=st.integers(min_value=1, max_value=20),
    b=st.integers(min_value=1, max_value=20),
    c=st.integers(min_value=1, max_value=20),
)
def test_integer_triples_match_reference(a, b, c):
    assert triangle_area(a, b, c) == reference_area(a, b, c)
